Perfect. Here's the plan:
- **Brittney** — remove her from the config table entirely so she disappears from the dashboard (her historical log entries stay untouched)
- **Debi** — set her `Weekly_Hours` to 42.5 so you can see her capacity tracked but you control the number manually

Since the Drive MCP can't write cells directly, here's a short Apps Script to do it. Open the sheet, go to **Extensions > Apps Script**, paste this in, and run `updateCapacityTracker`:

```javascript
function updateCapacityTracker() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = ss.getSheets();

  let configSheet = null;
  let headerRowIdx = -1;

  // Find the sheet that has the config table
  for (const sheet of sheets) {
    const data = sheet.getDataRange().getValues();
    for (let i = 0; i < data.length; i++) {
      if (data[i].includes('Weekly_Hours')) {
        configSheet = sheet;
        headerRowIdx = i;
        break;
      }
    }
    if (configSheet) break;
  }

  if (!configSheet) {
    SpreadsheetApp.getUi().alert('Could not find the config table (looking for "Weekly_Hours" header).');
    return;
  }

  const data = configSheet.getDataRange().getValues();
  const userCol = data[headerRowIdx].indexOf('User');
  const weeklyHrsCol = data[headerRowIdx].indexOf('Weekly_Hours');

  let brittneyRow = -1;
  let debiRow = -1;

  for (let i = headerRowIdx + 1; i < data.length; i++) {
    if (data[i][userCol] === 'Brittney Davis') brittneyRow = i + 1; // 1-indexed
    if (data[i][userCol] === 'Debi A Giwa') debiRow = i + 1;
  }

  // Set Debi's weekly hours to 42.5 FIRST (before any row deletion shifts indices)
  if (debiRow > 0) {
    configSheet.getRange(debiRow, weeklyHrsCol + 1).setValue(42.5);
  }

  // Remove Brittney from the config table
  if (brittneyRow > 0) {
    configSheet.deleteRow(brittneyRow);
  }

  const results = [];
  if (brittneyRow > 0) results.push('Brittney Davis removed from config');
  if (debiRow > 0) results.push('Debi A Giwa set to 42.5 hrs/wk');
  if (results.length === 0) results.push('No matching rows found — check names in config table');

  SpreadsheetApp.getUi().alert(results.join('\n'));
}
```

A few things to note:
- Brittney's **past time log entries remain intact** — only her row in the config table gets removed, so historical data won't be affected
- Debi's capacity will now show as **42.5 hrs/wk** and you can manually edit that cell anytime going forward
- After running, the `#DIV/0!` errors for both should resolve — Brittney disappears from the dashboard, Debi shows properly with her full capacity

Let me run a diagnostic first to see what the script is actually finding. Paste this into Apps Script and run `diagnose` — it won't change anything, just reports back:

```javascript
function diagnose() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = ss.getSheets();
  let report = 'Sheets found:\n';

  for (const sheet of sheets) {
    report += `  - "${sheet.getName()}"\n`;
  }

  report += '\nSearching for "Weekly_Hours" header...\n';

  for (const sheet of sheets) {
    const data = sheet.getDataRange().getValues();
    for (let i = 0; i < data.length; i++) {
      const row = data[i];
      for (let j = 0; j < row.length; j++) {
        if (String(row[j]).includes('Weekly_Hours')) {
          report += `  Found in sheet: "${sheet.getName()}", row ${i+1}, col ${j+1}\n`;
        }
        if (String(row[j]).includes('Brittney')) {
          report += `  "Brittney" found in sheet: "${sheet.getName()}", row ${i+1}, col ${j+1} -> value: "${row[j]}"\n`;
        }
        if (String(row[j]).includes('Debi')) {
          report += `  "Debi" found in sheet: "${sheet.getName()}", row ${i+1}, col ${j+1} -> value: "${row[j]}"\n`;
        }
      }
    }
  }

  SpreadsheetApp.getUi().alert(report);
  Logger.log(report);
}
```

Run `diagnose` and share what the alert says. That'll tell us exactly which sheet and row the config lives on so we can fix the update script.

Now I can see everything I need. The sheets are: **Dashboard**, **Weekly_Summary**, **Everhour_Import**, **Role_Capacity**, **Raw_Log**, **Deliverable_Dictionary**, **Delegation Mirror**.

The `Weekly_Hours` header wasn't found — which means the config is likely on the **Role_Capacity** sheet under a different column name. Let me run one more quick diagnostic just on that sheet. Replace the code and run `diagnoseRoleCapacity`:

```javascript
function diagnoseRoleCapacity() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName('Role_Capacity');

  if (!sheet) {
    SpreadsheetApp.getUi().alert('Role_Capacity sheet not found.');
    return;
  }

  const data = sheet.getDataRange().getValues();
  let report = 'Role_Capacity sheet contents (first 20 rows):\n\n';

  for (let i = 0; i < Math.min(20, data.length); i++) {
    report += `Row ${i+1}: ${JSON.stringify(data[i])}\n`;
  }

  SpreadsheetApp.getUi().alert(report);
  Logger.log(report);
}
```

Run `diagnoseRoleCapacity` and share what the alert says — that'll show me the exact column names and where Brittney and Debi live in the config.
